class _UniffiFfiConverterTypeElement:
    @staticmethod
    def lift(value: int) -> Element:
        return Element._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Element):
        if not isinstance(value, Element):
            raise TypeError("Expected Element instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Element) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Element:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Element, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterUInt64(_UniffiConverterPrimitiveInt):
    CLASS_NAME = "u64"
    VALUE_MIN = 0
    VALUE_MAX = 2**64

    @staticmethod
    def read(buf):
        return buf.read_u64()

    @staticmethod
    def write(value, buf):
        buf.write_u64(value)


